static wsound89_i16 sat(wsound89_i32 v){if(v>32767)return 32767;if(v<-32768)return -32768;return(wsound89_i16)v;}static wsound89_i16 nz(wsoundaero89_context*c){c->state=c->state*1664525U+1013904223U;return(wsound89_i16)((c->state>>16)&65535U);}static wsound89_i16 tri(wsound89_u32 p){wsound89_u16 x=(wsound89_u16)(p>>16);wsound89_i32 v=(x<32768U)?((wsound89_i32)x*2-32768):(98303-(wsound89_i32)x*2);return(wsound89_i16)v;}
wsound89_result wsoundaero89_init(wsoundaero89_context*c,wsound89_u32 rate,wsound89_u32 seed){if(!c||!rate)return WSOUND89_EINVAL;c->state=seed?seed:0x4145524FU;c->phase=0;c->phase_inc=0;c->age=0;c->total=0;c->env=0;c->low=0;c->band=0;c->speed_q15=0;c->size_q15=0;c->active=0;c->gate=0;c->mode=WSOUNDAERO89_BULLET;return WSOUND89_OK;}
wsound89_result wsoundaero89_trigger(wsoundaero89_context*c,wsoundaero89_mode m,wsound89_u16 speed,wsound89_u16 size,wsound89_u32 dur){if(!c||(wsound89_u32)m>5U)return WSOUND89_EINVAL;c->mode=m;c->speed_q15=speed;c->size_q15=size;c->phase_inc=250000U+((wsound89_u32)speed<<5)+((wsound89_u32)m*90000U);c->age=0;c->total=dur;c->env=(m==WSOUNDAERO89_ROCKET)?2500:22000;c->active=1;c->gate=1;return WSOUND89_OK;}void wsoundaero89_set_gate(wsoundaero89_context*c,int on){if(c)c->gate=(wsound89_u8)(on?1:0);}
wsound89_i16 wsoundaero89_process_sample(wsoundaero89_context*c){wsound89_i32 n,hp,body,t,mod,mix;if(!c||!c->active)return 0;n=nz(c);c->low+=(n-c->low)>>((c->mode==WSOUNDAERO89_ROCKET)?5:3);hp=n-c->low;c->band+=(c->low-c->band)>>3;body=c->low-c->band;c->phase+=c->phase_inc;t=tri(c->phase);mod=24576+(t>>3);if(c->mode==WSOUNDAERO89_ROCKET){mix=((body*(12000+(c->size_q15>>2)))>>15)+((hp*(2200+(c->speed_q15>>4)))>>15);mix=(mix*mod)>>15;}else if(c->mode==WSOUNDAERO89_PELLET_CLOUD){mix=((hp*(9000+(c->speed_q15>>2)))>>15)+(body>>1);}else if(c->mode==WSOUNDAERO89_GRENADE||c->mode==WSOUNDAERO89_DEBRIS){mix=((body*(10000+(c->size_q15>>2)))>>15)+(hp>>3);}else if(c->mode==WSOUNDAERO89_NEAR_CAMERA){mix=((hp*(15000+(c->speed_q15>>2)))>>15)+(body>>2);}else{mix=(hp*(12000+(c->speed_q15>>1)))>>15;}mix=(mix*c->env)>>15;c->age++;if(c->total&&c->age>=c->total)c->gate=0;if(c->gate)c->env+=(28000-c->env)>>7;else c->env-=(c->env>>6)+18;if(c->env<24){c->env=0;c->active=0;}return sat(mix);}
int wsoundaero89_is_active(const wsoundaero89_context*c){return c&&c->active;}
